<script setup>import {computed,ref} from 'vue';import RequestCard from '../components/RequestCard.vue';import {demoRequests} from '../data/demo.js';import {readStore} from '../data/storage.js';const filter=ref('Усі');const local=ref(readStore('requests',[]));const items=computed(()=>[...local.value,...demoRequests].filter(x=>filter.value==='Усі'||x.kind===filter.value));</script><template><div class="page-intro with-action"><div><h1>Звернення та запити</h1><p>Статуси перевірки визначаються партнерськими організаціями та медичними установами.</p></div><RouterLink class="btn-primary" to="/requests/new">+ Подати звернення</RouterLink></div><div class="filter-pills"><button v-for="type in ['Усі','Кров','Кістковий мозок','Лікування']" :key="type" :class="{active:filter===type}" @click="filter=type">{{type}}</button></div><div class="request-grid"><RequestCard v-for="item in items" :key="item.id" :request="item"/></div></template>